import { unstable_cache } from 'next/cache';
import { getAllProducts } from './db.js';

// Cached product fetching with "products" tag
export const getCachedProducts = unstable_cache(
  async () => {
    const products = await getAllProducts();
    return products;
  },
  ['products-list'],
  {
    tags: ['products'],
    revalidate: false // Only revalidate on explicit cache invalidation
  }
);

// Simulate sync from upstream ERP/PIM system
export async function syncCatalogFromUpstream() {
  // In production, this would:
  // - Fetch updated data from ERP/PIM APIs
  // - Update database with new pricing, inventory, availability
  // - Handle thousands of SKUs in batches

  // Simulate a time-consuming sync operation
  await new Promise(resolve => setTimeout(resolve, 2000));

  return {
    success: true,
    syncedAt: new Date().toISOString(),
    message: 'Catalog sync completed successfully'
  };
}

